if (i_uid_needs_update(idmap, attr, inode) ||
    i_gid_needs_update(idmap, attr, inode)) {
	handle_t *handle;
	struct dquot *transfer_to[MAXQUOTAS] = {};
	int qerror = 0;
	int i;

	if (i_uid_needs_update(idmap, attr, inode)) {
		kuid_t kuid = from_vfsuid(idmap, i_user_ns(inode),
					  attr->ia_vfsuid);
		transfer_to[USRQUOTA] = dqget(inode->i_sb,
					      make_kqid_uid(kuid));
		if (IS_ERR(transfer_to[USRQUOTA])) {
			if (PTR_ERR(transfer_to[USRQUOTA]) != -ESRCH)
				qerror = PTR_ERR(transfer_to[USRQUOTA]);
			transfer_to[USRQUOTA] = NULL;
		}
	}
	if (!qerror && i_gid_needs_update(idmap, attr, inode)) {
		kgid_t kgid = from_vfsgid(idmap, i_user_ns(inode),
					  attr->ia_vfsgid);
		transfer_to[GRPQUOTA] = dqget(inode->i_sb,
					      make_kqid_gid(kgid));
		if (IS_ERR(transfer_to[GRPQUOTA])) {
			if (PTR_ERR(transfer_to[GRPQUOTA]) != -ESRCH)
				qerror = PTR_ERR(transfer_to[GRPQUOTA]);
			transfer_to[GRPQUOTA] = NULL;
		}
	}

	if (qerror) {
		for (i = 0; i < MAXQUOTAS; i++)
			dqput(transfer_to[i]);
		return qerror;
	}

	/* (user+group)*(old+new) structure, inode write (sb,
	 * inode block, ? - but truncate inode update has it) */
	handle = ext4_journal_start(inode, EXT4_HT_QUOTA,
		(EXT4_MAXQUOTAS_INIT_BLOCKS(inode->i_sb) +
		 EXT4_MAXQUOTAS_DEL_BLOCKS(inode->i_sb)) + 3);
	if (IS_ERR(handle)) {
		error = PTR_ERR(handle);
		for (i = 0; i < MAXQUOTAS; i++)
			dqput(transfer_to[i]);
		goto err_out;
	}

	/* __dquot_transfer() calls back ext4_get_inode_usage() which
	 * counts xattr inode references.
	 */
	down_read(&EXT4_I(inode)->xattr_sem);
	error = __dquot_transfer(inode, transfer_to);
	up_read(&EXT4_I(inode)->xattr_sem);

	for (i = 0; i < MAXQUOTAS; i++)
		dqput(transfer_to[i]);

	if (error) {
		ext4_journal_stop(handle);
		return error;
	}
	/* Update corresponding info in inode so that everything is in
	 * one transaction */
	i_uid_update(idmap, attr, inode);
	i_gid_update(idmap, attr, inode);
	error = ext4_mark_inode_dirty(handle, inode);
	ext4_journal_stop(handle);
	if (unlikely(error)) {
		return error;
	}
}

